package detector

import (
	"bytes"
	"context"
	"encoding/json"
	"os"
	"path/filepath"
	"runtime"
	"slices"
	"strings"
	"testing"

	"github.com/step-security/dev-machine-guard/internal/detector/configaudit"
	"github.com/step-security/dev-machine-guard/internal/model"
)

// The shared contract is generated by the real guarded scanner over the
// fixture tree. Host-specific paths and the IDs derived from them are normalized.
func TestCondaGoldenProducer(t *testing.T) {
	if runtime.GOOS == model.PlatformWindows {
		t.Skip("canonical Unix fixture; wire round-trip and scanner tests also run on Windows")
	}
	home := goTestHome(t)
	root := filepath.Join(home, "code")
	condaWriteFixture(t, home, root)
	scanner, x := condaTestScanner(t, home)
	condaFixtureEnv(x, home)
	inv, audit := scanner.Scan(context.Background(), goTestTarget(home), []string{root}, nil)
	condaAssertRefs(t, inv, audit)
	type sections struct {
		Inventory *model.CondaInventory   `json:"conda_inventory"`
		Audit     *model.CondaConfigAudit `json:"conda_config_audit"`
	}
	pair := sections{inv, audit}
	raw, err := json.Marshal(pair)
	if err != nil {
		t.Fatal(err)
	}
	raw = []byte(strings.NewReplacer(
		home, "/home/conda-fixture",
		"/private/etc/conda", "/etc/conda",
		"/private/var/lib/conda", "/var/lib/conda",
		"/.config/binstar/data", "/Library/Application Support/binstar/data",
	).Replace(string(raw)))
	if err := json.Unmarshal(raw, &pair); err != nil {
		t.Fatal(err)
	}
	replacements := []string{}
	for _, s := range pair.Inventory.Sources {
		replacements = append(replacements, s.SourceID, configaudit.GoSourceID(goTestTarget(home).Username, s.Kind, s.Path))
	}
	for _, f := range pair.Audit.Files {
		replacements = append(replacements, f.SourceID, configaudit.GoSourceID(goTestTarget(home).Username, configaudit.CondaConfigKind(f.Scope), f.Path))
	}
	raw = []byte(strings.NewReplacer(replacements...).Replace(string(raw)))
	if err := json.Unmarshal(raw, &pair); err != nil {
		t.Fatal(err)
	}
	for i := range pair.Inventory.Sources {
		slices.Sort(pair.Inventory.Sources[i].DiscoveredSources)
	}
	slices.SortFunc(pair.Audit.Findings, func(a, b model.CargoConfigFinding) int {
		return strings.Compare(a.Code+a.SourceID+a.Key, b.Code+b.SourceID+b.Key)
	})
	slices.SortFunc(pair.Audit.Contexts, func(a, b model.CondaConfigContext) int {
		return strings.Compare(a.EnvironmentPath+"\x00"+a.ProjectPath+"\x00"+strings.Join(a.ConfigSourceIDs, ","), b.EnvironmentPath+"\x00"+b.ProjectPath+"\x00"+strings.Join(b.ConfigSourceIDs, ","))
	})
	slices.SortFunc(pair.Audit.CredentialFiles, func(a, b model.CondaCredentialFile) int {
		return strings.Compare(a.Path, b.Path)
	})
	condaAssertRefs(t, pair.Inventory, pair.Audit)
	raw, err = json.MarshalIndent(pair, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	raw = append(raw, '\n')
	path := "../model/testdata/conda_inventory_v1_golden.json"
	if os.Getenv("UPDATE_CONDA_GOLDEN") == "1" {
		if err := os.WriteFile(path, raw, 0o600); err != nil {
			t.Fatal(err)
		}
	}
	want, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(raw, want) {
		t.Fatal("producer differs from shared Conda golden; review the contract before regenerating")
	}
}
